using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using UIFramework;
using UnityEngine;
using AssetsModule;
using DataModule;
internal static class Program {
    const string Path="Assets/_Res/Addressable/01FirstBundle/Prefabs/UI/Panels/NoInternetPanel.prefab";
    static int scenarios,checks,failures;
    static void Check(bool value,string reason){checks++;if(!value)throw new Exception(reason);}
    static Dictionary<string,UIPanel> Cache(UIManager ui)=>(Dictionary<string,UIPanel>)typeof(UIManager).GetField("_uiPanelsDict",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(ui);
    static PanelConfig Bound(UIPanel panel)=>(PanelConfig)typeof(UIPanel).GetField("panelConfig",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(panel);
    static async Task Throws<T>(Func<Task> action,string reason)where T:Exception{try{await action();}catch(T){checks++;return;}throw new Exception("missing "+typeof(T).Name+": "+reason);}
    static async Task Scenario(string name,Func<Task> action){scenarios++;Rig.Reset();try{await action();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static async Task<UIManager> Start(){var ui=new UIManager();var init=ui.Init();Check(init!=null,"Init task missing");await init;Check(Cache(ui)!=null&&ui._panelsParent!=null,"actual root/cache missing");return ui;}
    static GameObject Prefab(bool panel=true,bool canvas=true)=>new GameObject("NoInternetPanel",panel,canvas);
    static PanelConfig Config(){var config=new PanelConfig{panelName="NoInternetPanel",layer=100};DataManager.Instance.ActualGlobal.panelConfigs.Add(config);return config;}
    static Task<UIPanel> Request(UIManager ui){var task=ui.GetPanel(Path);Check(task!=null,"GetPanel task missing");return task;}
    static async Task<int> Main(){
        await Scenario("Init creates original root and cache before its own completion",async()=>{var ui=await Start();Check(ui.initcomplete,"own Init flag");Check(ui._panelsParent.gameObject.name=="UIPanelsRoot"&&Rig.Instances==0,"original root identity");Check(AssetsManager.Instance.Requests.Count==0&&!Rig.Trace.Any(s=>s.StartsWith("camera")||s.StartsWith("data")),"Init invented asynchronous resource work");});
        await Scenario("cold request suspends without instance or cache before typed asset result",async()=>{var ui=await Start();var task=Request(ui);Check(AssetsManager.Instance.Requests.Count==1&&AssetsManager.Instance.Requests[0].Path==Path,"exact typed address");Check(!task.IsCompleted&&Rig.Instances==0&&Cache(ui).Count==0,"advanced before await");Config();AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());Check(await task!=null,"real panel result");});
        await Scenario("cold completed result is a real hidden clone under original panels parent",async()=>{var ui=await Start();var config=Config();var task=Request(ui);var prefab=Prefab();AssetsManager.Instance.Requests[0].Source.SetResult(prefab);var panel=await task;Check(panel!=null&&!ReferenceEquals(panel,prefab.Panel),"returned asset instead of instance");Check(ReferenceEquals(panel.transform.parent,ui._panelsParent)&&panel.name=="NoInternetPanel","parent/name");Check(!panel.gameObject.activeSelf&&ReferenceEquals(Cache(ui)[Path],panel),"hidden cache identity");Check(ReferenceEquals(Bound(panel),config),"original leaf config binding");Check(panel.gameObject.Canvas.renderMode==RenderMode.ScreenSpaceCamera&&panel.gameObject.Canvas.sortingOrder==100&&ReferenceEquals(panel.gameObject.Canvas.worldCamera,CameraModule.CameraManager.Instance.ActualCamera),"actual canvas/camera/config values");});
        await Scenario("hot request returns exact cached instance without another asset load",async()=>{var ui=await Start();Config();var first=Request(ui);AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());var panel=await first;int instances=Rig.Instances;Rig.Trace.Clear();var cached=await Request(ui);Check(ReferenceEquals(panel,cached)&&AssetsManager.Instance.Requests.Count==1&&Rig.Instances==instances,"cache hit reloaded");Check(Rig.Trace.Count==0,"hot path reconfigured dependencies");});
        await Scenario("two cold awaits recheck after completion and instantiate only once",async()=>{var ui=await Start();Config();var first=Request(ui);var second=Request(ui);Check(AssetsManager.Instance.Requests.Count==2&&!first.IsCompleted&&!second.IsCompleted,"invented in-flight task cache");AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());var a=await first;AssetsManager.Instance.Requests[1].Source.SetResult(null);var b=await second;Check(ReferenceEquals(a,b)&&Rig.Instances==1&&Cache(ui).Count==1,"missing original after-await race recheck");});
        await Scenario("typed asset failure propagates without instance or cache",async()=>{var ui=await Start();var task=Request(ui);var failure=new InvalidOperationException("typed asset failure");AssetsManager.Instance.Requests[0].Source.SetException(failure);await Throws<InvalidOperationException>(async()=>await task,"asset failure");Check(Cache(ui).Count==0&&Rig.Instances==0,"failed load cached");});
        await Scenario("null asset result preserves original null return without cache",async()=>{var ui=await Start();var task=Request(ui);AssetsManager.Instance.Requests[0].Source.SetResult(null);Check(await task==null&&Cache(ui).Count==0&&Rig.Instances==0,"fabricated null-asset panel");});
        await Scenario("missing UIPanel logs original error and does not cache a placeholder",async()=>{var ui=await Start();var task=Request(ui);AssetsManager.Instance.Requests[0].Source.SetResult(Prefab(false));Check(await task==null&&Cache(ui).Count==0&&Rig.Instances==1,"missing component semantics");Check(Rig.Trace.Any(s=>s.StartsWith("error:UIManager.GetPanel()")),"original component diagnostic missing");});
        await Scenario("instance failure does not cache",async()=>{var ui=await Start();var task=Request(ui);Rig.ThrowInstantiation=true;AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());await Throws<InvalidOperationException>(async()=>await task,"Instantiate failure");Check(Cache(ui).Count==0&&Rig.Instances==0,"failed clone cached");});
        await Scenario("hidden and cache insertion precede camera and config boundary calls",async()=>{var ui=await Start();Config();var task=Request(ui);bool sawHiddenCache=false,sawConfigUnboundBeforeSort=false;Rig.Boundary=boundary=>{if(boundary=="canvas.renderMode")sawHiddenCache=Cache(ui).TryGetValue(Path,out var existing)&&!existing.gameObject.activeSelf;if(boundary=="canvas.sortingOrder")sawConfigUnboundBeforeSort=Bound(Cache(ui)[Path])==null;};AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());await task;Check(sawHiddenCache&&sawConfigUnboundBeforeSort,"cache/hidden/leaf-init order");Check(Rig.Trace.IndexOf("canvas.renderMode")<Rig.Trace.IndexOf("camera.UICamera")&&Rig.Trace.IndexOf("camera.UICamera")<Rig.Trace.IndexOf("canvas.worldCamera")&&Rig.Trace.IndexOf("canvas.worldCamera")<Rig.Trace.IndexOf("data.GlobalInfo")&&Rig.Trace.IndexOf("data.GlobalInfo")<Rig.Trace.IndexOf("canvas.sortingOrder"),"original API order");});
        await Scenario("camera failure retains original already inserted hidden cache entry",async()=>{var ui=await Start();Config();var task=Request(ui);Rig.ThrowCamera=true;AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());await Throws<InvalidOperationException>(async()=>await task,"camera failure");Check(Cache(ui).ContainsKey(Path)&&!Cache(ui)[Path].gameObject.activeSelf,"invented cache rollback after original insertion");Check(ReferenceEquals(await Request(ui),Cache(ui)[Path])&&AssetsManager.Instance.Requests.Count==1,"partial cached hot path changed");});
        await Scenario("no Canvas branch returns cached panel without camera config or Init",async()=>{var ui=await Start();Config();var task=Request(ui);AssetsManager.Instance.Requests[0].Source.SetResult(Prefab(true,false));var panel=await task;Check(panel!=null&&Bound(panel)==null&&Cache(ui).Count==1,"no Canvas branch");Check(!Rig.Trace.Contains("camera.UICamera")&&!Rig.Trace.Contains("data.GlobalInfo"),"invented Canvas dependency");});
        await Scenario("missing configuration logs and preserves prefab sorting and null config",async()=>{var ui=await Start();var task=Request(ui);AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());var panel=await task;Check(panel.gameObject.Canvas.sortingOrder==1000&&Bound(panel)==null&&Cache(ui).Count==1,"fabricated missing config");Check(Rig.Trace.Any(s=>s.StartsWith("error:")),"missing config diagnostic");});
        await Scenario("config predicate compares exact instance name with original case",async()=>{var ui=await Start();DataManager.Instance.ActualGlobal.panelConfigs.Add(new PanelConfig{panelName="nointernetpanel",layer=13});var task=Request(ui);AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());var panel=await task;Check(Bound(panel)==null&&panel.gameObject.Canvas.sortingOrder==1000,"case folding added");});
        await Scenario("cached destroyed Unity reference is not silently replaced",async()=>{var ui=await Start();Config();var task=Request(ui);AssetsManager.Instance.Requests[0].Source.SetResult(Prefab());var panel=await task;panel.Destroyed=true;Check(ReferenceEquals(await Request(ui),panel)&&AssetsManager.Instance.Requests.Count==1,"invented destroyed-cache cleanup");});
        await Scenario("repeated Init resets cache and creates a new original root",async()=>{var ui=await Start();var cache=Cache(ui);var root=ui._panelsParent;await ui.Init();Check(!ReferenceEquals(cache,Cache(ui))&&!ReferenceEquals(root,ui._panelsParent)&&ui.initcomplete,"new idempotency behavior");});
        await Scenario("original leaf Init stores provided config including null",async()=>{var panel=new UIPanel();var config=new PanelConfig{panelName="actual",layer=7};panel.Init(config);Check(ReferenceEquals(Bound(panel),config),"config field not stored");panel.Init(null);Check(Bound(panel)==null,"null config normalized");await Task.CompletedTask;});
        await Scenario("GetPanel before Init fails through task without auto initialization",async()=>{var ui=new UIManager();var task=ui.GetPanel(Path);Check(task!=null,"missing async result");await Throws<NullReferenceException>(async()=>await task,"before Init");Check(ui._panelsParent==null&&!ui.initcomplete&&AssetsManager.Instance.Requests.Count==0,"automatic Init shortcut");});
        await Scenario("Init allocation failure does not write its own completion flag",async()=>{var ui=new UIManager();Rig.ThrowRootCreation=true;var task=ui.Init();Check(task!=null,"missing Init async result");await Throws<InvalidOperationException>(async()=>await task,"root allocation failure");Check(!ui.initcomplete&&ui._panelsParent==null,"early own-ready store");});
        Console.WriteLine($"RESULT scenarios={scenarios} checks={checks} failures={failures}");return failures==0?0:1;
    }
}
